import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

# read csv file generated by c++
df = pd.read_csv("prime_stats.csv") # read file produced by code.cpp

#compute poisson uncertainties (sqrt(n)) in py
df["twin_err"] = np.sqrt(df["twin"])
df["sexy_err"] = np.sqrt(df["sexy"])
df["fib_err"] = np.sqrt(df["fib"])
print(df)

#bar chart layout positioning
x = np.arange(len(df)) # makes array of consecutive integers starting at 0, up to number of rows
width = 0.25 #make bars 0.25, have 3 bars per interval and 1 break before next interval = 1

fig, ax = plt.subplots(figsize=(12, 6))

#add 'yerr' and 'capsize' to display error bars on each category
ax.bar(
    x - width, df["twin"], width, 
    yerr=df["twin_err"], label="Twin Pairs", #passes the calculated uncertainties directly to each set of bars.
    color="darkred", capsize=3, error_kw={'ecolor': 'black', 'linewidth': 1} # black error bars to stand out again coloured bars
)

ax.bar(
    x, df["sexy"], width, 
    yerr=df["sexy_err"], label="Sexy Pairs", 
    color="seagreen", capsize=3, error_kw={'ecolor': 'black', 'linewidth': 1} #adds horizontal caps at the top and bottom of each error bar so they are clearly visible.
)

ax.bar(
    x + width, df["fib"], width, 
    yerr=df["fib_err"], label="Fibonacci Primes", 
    color="darkviolet", capsize=3, error_kw={'ecolor': 'black', 'linewidth': 1}
)

#format labels, ticks and grids
ax.set_xlabel("Range", fontsize=11, fontweight="bold")
ax.set_ylabel("Count", fontsize=11, fontweight="bold")
ax.set_title("Prime Pair Frequencies by Range (with $\\sqrt{N}$ Poisson Uncertainties)", fontsize=13, fontweight="bold")
ax.set_xticks(x)
ax.set_xticklabels(df["range"], rotation=45, ha="right") # labels x axis
ax.grid(axis="y", linestyle="--", alpha=0.5) #adds background gridlines aligned with the y-axis to help gauge whether error bars overlap across bins
ax.legend()

#calculate consecutive differences across bins
df["twin_diff"] = df["twin"].diff() # N2 - N1
df["u_diff"] = np.sqrt(df["twin"] + df["twin"].shift(1)) # sqrt(u1^2 + u2^2) = sqrt(N1 + N2)
df["diff_of_u"] = (df["twin_err"] - df["twin_err"].shift(1)).abs() # |u2 - u1|

print(df[["range", "twin", "twin_diff", "diff_of_u", "u_diff"]])

plt.tight_layout()
plt.savefig("prime_stats_plot.png", dpi=300)
plt.show()